/*!
 * Zeugma · démarrage de l'application
 *
 * Dernier module chargé (couche « app » du manifeste) : monte le studio dans #app avec la configuration
 * de l'instance (globalThis.DominoConfig, domino.config.js). Une autre page peut monter le studio, ou un
 * éditeur seul, sans ce fichier : Domino.studio(el, { config }) ou new Domino.Editor(el, langage).
 */
(function (root) {
  'use strict';
  const D = root.Domino, doc = root.document;
  const host = doc && doc.getElementById('app');
  if (!D || !host || host.dataset.manual !== undefined) return;
  D.studio(host, { config: root.DominoConfig }).then((studio) => {
    root.studio = studio;
    // Les polices arrivent après le premier dessin : les pierres se remesurent.
    if (doc.fonts && doc.fonts.ready) doc.fonts.ready.then(() => { root.DominoKit.clearCache(); studio._eachEditor((ed) => ed.render()); });
  }).catch((err) => {
    console.error(err);
    host.innerHTML = `<p style="padding:24px;font:14px system-ui;color:#b00">Le studio n’a pas pu démarrer : ${String((err && err.message) || err).replace(/</g, '&lt;')}</p>`;
  });
})(typeof globalThis !== 'undefined' ? globalThis : window);
